    if(type==='open'){if(currentException())errors.push('已有待处理异常，不能重复登记。');if(!['取消待处理','退款待处理','取消/退款待处理'].includes(data.exceptionType))errors.push('请选择异常类型。');if(!data.reason)errors.push('异常原因必填。');after.paused=true;}
